_Static_assert(sizeof(space_hdr_t) <= SK_STATE_BYTES,
               "the Space header fits the arena prefix (SD1)");

static inline space_hdr_t *space_hdr(const fx_share_t *share)
{
    return (space_hdr_t *)sk_state(share);
}

